"""Twelve original TMA and consumptive-coagulopathy questions."""
from create_itp_hit import rows,q,IT,IC,ID,HT
from qbank_authoring import ref
TD=ref('ISTH: Diagnosis of TTP Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC8146131/')
TT=ref('ISTH: TTP Treatment Focused Update, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC13470878/')
AD=ref('FDA: Adzynma Neutralizing-Antibody Boxed Warning Action, September 2026','https://www.fda.gov/vaccines-blood-biologics/safety-availability-biologics/fda-takes-action-new-boxed-warning-adzynma-enzyme-replacement-therapy-congenital-thrombotic')
EC=ref('CDC: STEC Clinical Guidance','https://www.cdc.gov/ecoli/hcp/guidance/index.html')
CM=ref('Nephrology Society Consensus: Complement-Mediated TMA Diagnosis and Treatment','https://pmc.ncbi.nlm.nih.gov/articles/PMC12784606/')
DI=ref('ISTH SSC Communication: DIC and Diagnostic Biomarkers','https://www.jthjournal.org/article/S1538-7836%2822%2907648-6/fulltext')
q('Which result is characteristic of TTP in a compatible acute TMA syndrome?', 'Severely reduced ADAMTS13 activity, typically below 10%',[
 ('A positive DAT as the defining criterion','TTP is a fragmentation rather than a standard immune red-cell-coating syndrome.'),('A normal platelet count as mandatory','Thrombocytopenia is characteristic.'),('Low serum iron as the defining assay','This does not identify the TTP mechanism.')],
 'ADAMTS13 normally cleaves ultralarge VWF multimers', '**Severe deficiency permits platelet-rich microvascular thrombosis.**',['Immune inhibition is the common acquired mechanism.','Congenital deficiency has a different etiological basis.'], '**Obtain a pretreatment sample when possible without delaying care.**',['Plasma treatment can affect the assay.','Interpret activity and inhibitor/antibody testing in context.'],[['Enzyme','ADAMTS13'],['Severe deficiency','Usually <10%'],['Effect','Platelet-rich microthrombi']],[TD])
q('An adult has severe thrombocytopenia, schistocytes, hemolysis and acute neurological changes with a high clinical probability of immune TTP. What is the priority?', 'Urgent TTP-directed treatment, including plasma exchange and corticosteroids, while obtaining rapid ADAMTS13 testing and considering indicated adjuncts',[
 ('Wait several days for ADAMTS13 before any treatment','Delay can be fatal.'),('Treat as ITP with observation alone','The fragmentation and organ injury point to a different emergency.'),('Give iron alone until the smear normalizes','This does not address microvascular thrombosis.')],
 'The treatment decision may precede final assay confirmation', '**Draw the ADAMTS13 sample promptly before plasma when feasible.**',['Use clinical probability and rapid testing to guide caplacizumab.','Rituximab addresses the immune mechanism in appropriate cases.'], '**Provide coordinated specialist and organ support.**',['A classic complete pentad is not required.','Reassess if results or the course suggest another TMA.'],[['Immediate','Plasma exchange and immune treatment'],['Diagnosis','Rapid pretreatment ADAMTS13 sample'],['Adjuncts','Caplacizumab / rituximab as indicated']],[TD,TT],style='clinical_scenario')
q('What is caplacizumab’s principal action in immune TTP?', 'Blocking VWF interaction with platelet GPIb',[
 ('Eliminating every ADAMTS13 autoantibody directly','It does not replace immune suppression.'),('Replacing the ADAMTS13 enzyme','That is a different therapeutic mechanism.'),('Activating fibrinogen binding to GPIIb/IIIa','It inhibits the relevant adhesion pathway rather than promoting aggregation.')],
 'Rapid antithrombotic protection does not cure the immune cause', '**Caplacizumab limits VWF-mediated platelet adhesion.**',['It can help control the acute microthrombotic process.','ADAMTS13 deficiency can persist despite platelet-count recovery.'], '**Continue cause-directed immune treatment and monitoring.**',['Bleeding is an important adverse effect.','Do not equate a normal count with resolved autoimmunity.'],[['Target effect','VWF–GPIb interaction blockade'],['Benefit','Reduced ongoing platelet-rich microthrombosis'],['Limit','Immune cause still needs treatment']],[TT])
q('What is the role of the PLASMIC score in suspected TTP?', 'Estimating the probability of severe ADAMTS13 deficiency while urgent definitive testing is arranged',[
 ('Replacing ADAMTS13 measurement in every patient','It is a probability tool with limitations.'),('Diagnosing every cause of TMA as TTP','TMA has several mechanisms.'),('Measuring the activity of complement factor H','It does not perform that assay.')],
 'A rapid clinical score supports early decision-making', '**The score combines clinical and laboratory variables associated with severe ADAMTS13 deficiency.**',['Performance depends on the population and data quality.','Cancer, transplant and other contexts can complicate interpretation.'], '**Do not let the score delay emergency treatment in a compelling case.**',['Obtain the actual enzyme assay.','Reassess the diagnosis as results return.'],[['Tool','Pretest probability estimate'],['Definitive assay','ADAMTS13'],['Use','Urgent decision support']],[TD])
q('What is the usual approach to prophylactic platelet transfusion in TTP without bleeding?', 'Avoid routine count correction; reserve platelets for a compelling bleeding or procedural indication after specialist assessment',[
 ('Transfuse to a normal count in every case before plasma exchange','This is not the standard approach in a platelet-thrombotic syndrome.'),('Platelets are forbidden even in catastrophic hemorrhage','A critical bleeding indication can override routine avoidance.'),('Platelets replace ADAMTS13 and treat the cause','They do not restore the deficient enzyme.')],
 'The low count reflects consumption in microvascular thrombosis', '**Routine transfusion is not the disease-directed treatment.**',['Urgent plasma and immune-directed therapy address the mechanism.','Bleeding and procedural exceptions require clinical judgment.'], '**Treat the patient rather than a target count alone.**',['Assess the site and severity of hemorrhage.','Do not postpone essential TTP therapy to normalize the count.'],[['No bleeding','No routine platelet correction'],['Critical indication','Specialist risk-benefit decision'],['Cause treatment','TTP-specific therapy']],[TT])
q('Compared with classic TTP, which laboratory pattern more strongly supports DIC in an appropriate septic patient?', 'Prolonged PT with increased fibrin-related markers and a consumptive trend in platelets and fibrinogen',[
 ('Severe ADAMTS13 deficiency as the usual DIC-defining result','That is the characteristic TTP assay.'),('An isolated normal coagulation profile as mandatory for DIC','DIC often affects global coagulation tests.'),('A positive DAT as the required DIC criterion','It is not required.')],
 'DIC involves systemic coagulation activation and consumption', '**Use the clinical trigger and serial tests.**',['Fibrinogen can be normal or high early because it is an acute-phase protein.','No single laboratory result captures all stages.'], '**Distinguish the dominant mechanism promptly.**',['TTP often has relatively preserved routine coagulation tests.','Sepsis, liver disease and overlapping processes can complicate the pattern.'],[['DIC','Coagulation activation and consumption'],['TTP','Severe ADAMTS13-related platelet microthrombi'],['Assessment','Trigger plus serial coagulation profile']],[DI,TD],style='clinical_scenario')
q('A child develops MAHA, thrombocytopenia and AKI after bloody diarrhea; stool testing detects Shiga toxin. Which syndrome is most likely?', 'STEC-associated hemolytic uremic syndrome',[
 ('Immune TTP established solely from the triad','The positive Shiga-toxin evidence identifies another important mechanism.'),('Isolated ITP','Hemolysis and renal injury require a broader diagnosis.'),('Warm AIHA','The fragmentation/renal phenotype is not the classic immune-coating syndrome.')],
 'A TMA triad does not uniquely identify TTP', '**Shiga toxin can produce endothelial injury and HUS.**',['Renal involvement can be severe.','Supportive and renal care are central.'], '**Avoid harmful reflex treatment of the preceding enteric infection.**',['CDC advises against antimotility agents in STEC.','Antibiotics in suspected STEC can increase HUS risk and are not routine treatment of that enteric syndrome.'],[['Trigger','STEC'],['Syndrome','MAHA, low platelets and AKI'],['Care','Supportive and renal management']],[EC],style='clinical_scenario')
q('A renal-predominant TMA persists after TTP and STEC have been assessed and relevant secondary causes reviewed. Which mechanism deserves evaluation?', 'Complement-mediated TMA',[
 ('A normal C3 level definitively excludes complement involvement','Circulating C3 can be normal.'),('No detected complement variant makes the diagnosis impossible','Genetic testing is not fully sensitive for the clinical syndrome.'),('Every TMA after diarrhea must be STEC regardless of testing','Triggers and mechanisms can overlap.')],
 'Complement dysregulation can drive severe endothelial injury', '**The diagnosis integrates exclusion and positive clinical evidence.**',['Genetic and autoantibody studies can inform prognosis and recurrence.','Urgent treatment may be needed before genetic results return.'], '**Use specialist complement-inhibition assessment when indicated.**',['Eculizumab or ravulizumab are important C5-directed options in suitable disease.','Vaccination and infection-risk precautions remain essential.'],[['Mechanism','Complement dysregulation'],['Tests','Supportive and prognostic, not always definitive'],['Treatment','Timely expert-directed inhibition when indicated']],[CM],style='clinical_scenario')
q('What does a normal C3 concentration mean in suspected complement-mediated TMA?', 'It does not exclude the diagnosis',[
 ('It proves absence of alternative-pathway activity','Systemic concentrations do not fully reflect local dysregulation.'),('It confirms immune TTP','ADAMTS13 assessment answers that question.'),('It proves the kidney injury is prerenal','That requires a different clinical assessment.')],
 'A screening concentration is not a complete functional pathway assessment', '**Complement-mediated endothelial disease can occur with normal circulating C3.**',['A low result can support concern but is not specific.','Genetic and antibody findings also have limitations.'], '**Interpret the entire TMA presentation.**',['Exclude urgent alternative mechanisms.','Do not delay an indicated specialist treatment decision solely because C3 is normal.'],[['C3 normal','Does not rule out'],['C3 low','Supportive but nonspecific'],['Decision','Integrated TMA assessment']],[CM])
q('What is the disease-specific replacement principle in congenital TTP?', 'Replace ADAMTS13, using recombinant enzyme or plasma-based treatment according to current guidance, access and safety',[
 ('Rituximab is mandatory because every congenital case has an autoantibody','The congenital mechanism is inherited deficiency rather than the usual acquired inhibitor.'),('Platelet transfusion alone replaces the enzyme','It does not.'),('No prophylaxis can ever be useful between episodes','Replacement can prevent episodes and long-term injury.')],
 'Congenital and immune TTP need different cause-directed strategies', '**ISTH 2025 supports ADAMTS13 replacement, favoring recombinant treatment where appropriate and accessible.**',['Plasma remains an alternative in defined circumstances.','The later 2026 FDA antibody warning must also be incorporated.'], '**Monitor activity and treatment response.**',['Breakthrough disease requires urgent reassessment.','Do not assume an enzyme-replacement product is free of immunogenicity risk.'],[['Congenital defect','ADAMTS13 deficiency'],['Replacement','Recombinant or plasma pathway'],['Monitoring','Activity, response and inhibitors']],[TT,AD])
q('A congenital-TTP patient receiving recombinant ADAMTS13 develops reduced enzyme response and recurrent symptoms. What new safety concern must be assessed?', 'Neutralizing antibodies to ADAMTS13',[
 ('An inhibitor is impossible because the product is recombinant','Postmarketing neutralizing antibodies have been reported.'),('A normal past response guarantees lifelong efficacy','Immunogenicity can emerge later.'),('The only explanation is dietary iron deficiency','This does not explain loss of enzyme activity and TTP recurrence.')],
 'Current treatment evidence includes postmarketing safety information', '**FDA’s September 2026 communication described serious outcomes from blocking antibodies.**',['The concern can reduce response to recombinant or plasma-derived ADAMTS13.','Baseline and periodic inhibitor/activity monitoring are relevant.'], '**Arrange urgent specialist reassessment of breakthrough disease.**',['Do not advise unsupervised treatment cessation.','A replacement and rescue plan must account for inhibitor status.'],[['Signal','Loss of activity or response'],['Concern','Neutralizing antibody'],['Action','Urgent testing and specialist treatment plan']],[AD],style='clinical_scenario')
q('What is the central treatment principle for DIC associated with sepsis?', 'Treat the underlying cause and provide individualized hemostatic and organ support',[
 ('Normalize every coagulation test with plasma regardless of symptoms','Laboratory correction alone is not the principal goal.'),('Ignore bleeding because DIC is only thrombosis','Bleeding and thrombosis can coexist.'),('Platelet transfusion alone cures the septic trigger','It does not address the underlying process.')],
 'DIC is a syndrome driven by another serious disease', '**Infection control and physiological support are fundamental.**',['Blood components are selected for bleeding, procedures and the demonstrated deficit.','Serial trends matter more than an isolated result.'], '**Balance bleeding and thrombosis risk.**',['Prophylactic anticoagulation may be relevant when safe.','A patient with active major hemorrhage needs a different support strategy from one with only abnormal tests.'],[['Cause','Control the trigger'],['Support','Organs and indicated blood components'],['Monitoring','Serial clinical and coagulation assessment']],[DI])
